// TypeScript Version: 4.1

/**
* Rounds a single-precision floating-point numeric value to the nearest multiple of `10^n` toward positive infinity.
*
* ## Notes
*
* -   When operating on single-precison floating-point numbers in bases other than `2`, rounding to specified digits can be inexact.
*
* @param x - input value
* @param n - integer power of 10
* @returns rounded value
*
* @example
* // Round a value to 2 decimal places:
* var v = ceilnf( 3.141592653589793f, -2f );
* // returns 3.15f
*
* @example
* // If n = 0, `ceilnf` behaves like `ceil`:
* var v = ceilnf( 3.141592653589793f, 0f );
* // returns 4.0f
*
* @example
* // Round a value to the nearest thousand:
* var v = ceilnf( 12368.0f, 3f );
* // returns 13000.0f
*/
declare function ceilnf( x: number, n: number ): number;


// EXPORTS //

export = ceilnf;
